module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter JR = 6'b001000,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);


	wire [32:0] res;
	wire [4:0] shamt;
	wire signed	[31:0]	a_signed;
	wire signed	[31:0]	b_signed;
	wire [31:0] add_sub;
	wire carry_add;
	wire carry_sub;
	wire overflow_add;
	wire overflow_sub;
	wire less_signed;
	wire less_unsigned;
	wire lui;

	assign	a_signed	= $signed(a);
	assign	b_signed	= $signed(b);
	assign	add_sub	= a_signed - b_signed;
	assign	carry_add	= res[32];
	assign	carry_sub	= res[32];
	assign	overflow_add	= (~a[31] & ~b[31] & res[31]) | (a[31] & b[31] & ~res[31]);
	assign	overflow_sub	= (a[31] & ~b[31] & ~res[31]) | (~a[31] & b[31] & res[31]);
	assign	less_signed	= (aluc == SLT && add_sub[31]) ? 1 : 0;
	assign	less_unsigned	= (aluc == SLTU && !res[32]) ? 1 : 0;
	assign	lui			= (aluc == LUI) ? 1 : 0;
	assign	shamt			= a[4:0];
	assign	flag			= less_signed | less_unsigned;
	assign	carry			= (aluc == ADD || aluc == ADDU) ? carry_add : carry_sub;
	assign	negative		= res[31];
	assign	overflow		= (aluc == ADD || aluc == ADDU) ? overflow_add : overflow_sub;

	assign	res		= (aluc == SLL ) ? (b << shamt) :
						(aluc == SRL ) ? (b >> shamt) :
						(aluc == SRA ) ? (b_signed >>> shamt) :
						(aluc == SLLV) ? (b << a[4:0]) :
						(aluc == SRLV) ? (b >> a[4:0]) :
						(aluc == SRAV) ? (b_signed >>> a[4:0]) :
						(aluc == LUI ) ? ({a[15:0], 16'b0}) :
						(aluc == ADD || aluc == ADDU) ? (a + b) :
						(aluc == SUB || aluc == SUBU) ? (add_sub) :
						(aluc == AND ) ? (a & b) :
						(aluc == OR  ) ? (a | b) :
						(aluc == XOR ) ? (a ^ b) :
						(aluc == NOR ) ? (~(a | b)) :
						(aluc == SLT ) ? {{31{1'b0}}, less_signed} :
						(aluc == SLTU) ? {{31{1'b0}}, less_unsigned} :
												  32'bZ ;

	assign	r	= res[31:0];
	assign	zero	= (res[31:0] == 32'd0) ? 1 : 0;
endmodule
